import pytest

from timecode import parse_timecode, make_timecode
from frame_math import (
    duration_between,
    frames_to_timecode,
    round_trip_frames,
    timecode_to_frames,
)


def TC(text):
    return parse_timecode(text)


# --- happy path: a short drop-frame offset before any frame is dropped ------

def test_one_second_drop_frame_is_thirty_frames():
    # The first whole second has dropped nothing yet, so it is 30 frames.
    assert timecode_to_frames(TC("00:00:01;00")) == 30


def test_non_drop_is_plain_base_thirty_arithmetic():
    # Non-drop never skips a label: one minute is exactly 30 * 60 frames.
    assert timecode_to_frames(TC("00:01:00:00")) == 1800


# --- minute boundary where two labels are dropped ---------------------------

def test_first_minute_drops_two_labels():
    # ;00 and ;01 of minute 1 do not exist; the minute starts at ;02.
    assert timecode_to_frames(TC("00:01:00;02")) == 1800


def test_minute_one_frame_zero_is_not_a_real_label():
    # 00:01:00;00 is not a legal drop-frame label, but if it is read at all it
    # must not share a frame index with the real start of minute 1.
    assert timecode_to_frames(TC("00:01:00;02")) != timecode_to_frames(
        TC("00:00:59;29")
    ) - 1


# --- the every-tenth-minute exception ---------------------------------------

def test_tenth_minute_does_not_drop():
    # Minute 10 is a multiple of ten, so ;00 is a legal label and nothing is
    # skipped at its head. Only minutes 1..9 dropped two each: 9 * 2 = 18.
    assert timecode_to_frames(TC("00:10:00;00")) == 10 * 1800 - 18


def test_tenth_minute_boundary_against_naive_count():
    # A naive "drop on every minute" would skip 20 labels by minute 10; the
    # NTSC scheme skips only 18 because the tenth minute is exempt.
    assert timecode_to_frames(TC("00:10:00;00")) == 17982


def test_one_hour_is_ntsc_correct_frame_count():
    # The defining anchor: one hour of 29.97 footage is 107892 frames.
    assert timecode_to_frames(TC("01:00:00;00")) == 107892


# --- invalid / unexpected input ---------------------------------------------

def test_garbage_timecode_is_rejected():
    with pytest.raises(ValueError):
        parse_timecode("1:2:3:4")


def test_frame_field_out_of_range_is_rejected():
    with pytest.raises(ValueError):
        make_timecode(0, 0, 0, 30, drop_frame=True)


def test_negative_frame_index_is_rejected():
    with pytest.raises(ValueError):
        frames_to_timecode(-1, drop_frame=True)


# --- round trips: the regression the bug breaks -----------------------------

@pytest.mark.parametrize(
    "frame_index",
    [0, 30, 1800, 1798, 17982, 53946, 107892, 215784],
)
def test_drop_frame_round_trip_is_identity(frame_index):
    assert round_trip_frames(frame_index, drop_frame=True) == frame_index


@pytest.mark.parametrize("frame_index", [0, 1, 30, 1800, 108000, 1296000])
def test_non_drop_round_trip_is_identity(frame_index):
    assert round_trip_frames(frame_index, drop_frame=False) == frame_index


# --- duration helper built on top of the conversion -------------------------

def test_duration_over_one_hour_has_no_drift():
    # Across a full hour the drop-frame span must equal the NTSC frame count,
    # not the naive 108000 a 30-fps count would give.
    span = duration_between(TC("00:00:00;00"), TC("01:00:00;00"))
    assert span == 107892


def test_duration_across_a_ten_minute_block():
    span = duration_between(TC("00:00:00;00"), TC("00:10:00;00"))
    assert span == 17982


def test_mixing_schemes_is_rejected():
    with pytest.raises(ValueError):
        duration_between(TC("00:00:00;00"), TC("00:10:00:00"))
